SELECT CASE WHEN duration_sec >= 391 THEN 'high' WHEN duration_sec >= 97 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM web_events GROUP BY CASE WHEN duration_sec >= 391 THEN 'high' WHEN duration_sec >= 97 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(duration_sec), 2) > 49 ORDER BY duration_sec_bucket DESC, avg_duration_sec;
